$ProjectPath=[IO.Path]::GetFullPath($ProjectPath);$utf8=New-Object Text.UTF8Encoding($false,$true);$records=New-Object Collections.Generic.List[object]
function New-VersionedWrapper([string]$SourceRelative,[string]$ExpectedSha,[string]$OutputRelative,[object[]]$Routes){$source=Join-Path $ProjectPath $SourceRelative.Replace('/','\');$output=Join-Path $ProjectPath $OutputRelative.Replace('/','\');if(Test-Path $output){throw "Create-new wrapper exists: $output"};$actual=(Get-FileHash $source -Algorithm SHA256).Hash.ToLowerInvariant();if($actual-ne$ExpectedSha){throw "Source wrapper hash mismatch for $SourceRelative`: $actual"};$text=[IO.File]::ReadAllText($source,[Text.Encoding]::UTF8);$changes=New-Object Collections.Generic.List[object];foreach($route in $Routes){$count=$text.Split([string[]]@([string]$route.old),[StringSplitOptions]::None).Count-1;if($count-ne[int]$route.count){throw "Wrapper route count $count, expected $($route.count), for $($route.old) in $SourceRelative"};$text=$text.Replace([string]$route.old,[string]$route.new);$changes.Add([pscustomobject]@{from=$route.old;to=$route.new;count=$count})};[IO.File]::WriteAllText($output,$text,$utf8);$tokens=$null;$errors=$null;[Management.Automation.Language.Parser]::ParseFile($output,[ref]$tokens,[ref]$errors)|Out-Null;if(@($errors).Count){throw "Generated wrapper parser errors: $($errors.Message-join'; ')"};$records.Add([pscustomobject]@{sourceRelativePath=$SourceRelative;sourceSha256=$actual;outputRelativePath=$OutputRelative;outputSha256=(Get-FileHash $output -Algorithm SHA256).Hash.ToLowerInvariant();routes=$changes.ToArray()})}

